import { useEffect, useState } from "react";

// Fetches and renders backend/publish_research_results.py's output - the one
// place the real, computed Mars30 study results reach the UI. Every number
// shown here traces to a file generated by backend code (never invented in
// this component): baseline_results.json, mars30_schedule_comparison.json,
// and the published pipeline's scoring_summary.json.
export default function ResearchResults({ manifest }) {
  const [data, setData] = useState(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetch("/data/research/results.json")
      .then((response) => {
        if (!response.ok) throw new Error("Results unavailable");
        return response.json();
      })
      .then((report) => { if (!cancelled) setData(report); })
      .catch(() => { if (!cancelled) setError(true); });
    return () => { cancelled = true; };
  }, []);

  if (error) return (
    <section className="pv-panel pv-consultations">
      <div className="pv-panel-head"><h2>Fixed versus adaptive results</h2></div>
      <h3>Results file not found</h3>
      <p>Run <code>python backend/publish_research_results.py</code> to generate it.</p>
    </section>
  );
  if (!data) return (
    <section className="pv-panel pv-consultations" role="status">
      <div className="pv-panel-head"><h2>Fixed versus adaptive results</h2></div>
      <p>Loading the computed study results…</p>
    </section>
  );

  const ds = data.dataset;
  const sansRows = Object.entries(data.ml_baseline.sans);
  const venousRows = Object.entries(data.ml_baseline.venous);
  const intervals = Object.entries(data.fixed_vs_adaptive.by_interval);

  return (
    <section className="pv-panel pv-consultations">
      <div className="pv-panel-head"><h2>Fixed versus adaptive results</h2><span className="pv-tag">{data.label}</span></div>
      <p className="pv-notice">{data.disclaimer}</p>
      {data.correction_notice && <p className="pv-notice">{data.correction_notice}</p>}

      <h3>Dataset</h3>
      <dl>
        <div><dt>Loaded cohort</dt><dd>{ds.astronauts} astronauts · {ds.mission_days} days · {ds.records.toLocaleString()} records (seed {manifest?.random_seed ?? 2026})</dd></div>
        <div><dt>Train / val / test split</dt><dd>{ds.split.train_astronauts} / {ds.split.val_astronauts} / {ds.split.test_astronauts} astronauts, split by astronaut</dd></div>
        <div><dt>Scenario mix</dt><dd>healthy {ds.scenario_mix.healthy} · SANS-only {ds.scenario_mix.sans_only} · venous-only {ds.scenario_mix.venous_only} · both {ds.scenario_mix.both}</dd></div>
        <div><dt>Validation</dt><dd>{ds.validated}</dd></div>
      </dl>

      <h3>ML baseline (reference bar, test split)</h3>
      <div className="pv-table-wrap"><table className="pv-data-table">
        <thead><tr><th>SANS model</th><th>Test AUROC</th><th>Detected</th><th>Median delay (days)</th><th>Event-free alerted</th></tr></thead>
        <tbody>{sansRows.map(([name, row]) => (
          <tr key={name}><th scope="row">{name}</th><td>{row.test_auroc}</td><td>{row.detected}</td><td>{row.median_delay_days ?? "—"}</td><td>{(row.false_alarm_astronaut_rate * 100).toFixed(1)}%</td></tr>
        ))}</tbody>
      </table></div>
      <div className="pv-table-wrap"><table className="pv-data-table">
        <thead><tr><th>Venous model</th><th>Test AUROC</th><th>Detected</th><th>Median delay (days)</th><th>Event-free alerted</th></tr></thead>
        <tbody>{venousRows.map(([name, row]) => (
          <tr key={name}><th scope="row">{name}</th><td>{row.test_auroc}</td><td>{row.detected}</td><td>{row.median_delay_days ?? "—"}</td><td>{(row.false_alarm_astronaut_rate * 100).toFixed(1)}%</td></tr>
        ))}</tbody>
      </table></div>

      <h3>SANS Bayesian rule - full cohort tier distribution</h3>
      <p>{data.sans_bayesian_rule.description}</p>
      <div className="pv-table-wrap"><table className="pv-data-table">
        <thead><tr><th>Outcome</th>{Object.keys(data.sans_bayesian_rule.full_cohort_tier_distribution.sans).map((t) => <th key={t}>{t}</th>)}</tr></thead>
        <tbody>
          <tr><th scope="row">SANS</th>{Object.values(data.sans_bayesian_rule.full_cohort_tier_distribution.sans).map((v, i) => <td key={i}>{v.toLocaleString()}</td>)}</tr>
        </tbody>
      </table></div>

      <h3>Fixed versus adaptive SANS scheduling</h3>
      <p>{data.fixed_vs_adaptive.description}</p>
      <p>Trigger accuracy used: {data.fixed_vs_adaptive.trigger_accuracy_used} (approved sweep: {data.fixed_vs_adaptive.trigger_accuracy_approved_sweep.join(", ")}). {data.fixed_vs_adaptive.n_event_astronauts} event astronauts, {data.fixed_vs_adaptive.n_nonevent_astronauts} non-event astronauts.</p>
      {intervals.map(([interval, row]) => (
        <div key={interval}>
          <h4>{interval} interval</h4>
          <div className="pv-table-wrap"><table className="pv-data-table">
            <thead><tr><th>Policy</th><th>Scans used</th><th>Detected</th><th>Missed</th><th>Median delay (days)</th><th>False-escalation rate</th></tr></thead>
            <tbody>
              <tr><th scope="row">Fixed</th><td>{row.fixed.total_scans.toLocaleString()}</td><td>{row.fixed.detected}</td><td>{row.fixed.missed}</td><td>{row.fixed.median_delay_days}</td><td>{(row.fixed.false_escalation_rate * 100).toFixed(1)}%</td></tr>
              <tr><th scope="row">Adaptive</th><td>{row.adaptive.total_scans.toLocaleString()}</td><td>{row.adaptive.detected}</td><td>{row.adaptive.missed}</td><td>{row.adaptive.median_delay_days}</td><td>{(row.adaptive.false_escalation_rate * 100).toFixed(1)}%</td></tr>
            </tbody>
          </table></div>
          <p className="pv-comparison-finding">+{row.extra_scans_used_by_adaptive.toLocaleString()} extra scans for adaptive · {row.total_days_saved_by_adaptive.toLocaleString()} total detection-days saved · {row.days_saved_per_additional_scan ?? "—"} days saved per extra scan.</p>
        </div>
      ))}

      <h3>Completed synthetic experiments</h3>
      <ul>{data.completed_synthetic_experiments.map((text) => <li key={text}>{text}</li>)}</ul>

      <h3>Scientific assumptions and limitations</h3>
      <ul>{data.scientific_assumptions_and_limitations.map((text) => <li key={text}>{text}</li>)}</ul>

      <h3>Genuinely blocked future work</h3>
      <ul>{data.genuinely_blocked_future_work.map((text) => <li key={text}>{text}</li>)}</ul>

      <p><a href="#engineering-dashboard">Inspect the separate, labeled engineering acceptance cases (E1-E5)</a></p>
    </section>
  );
}
